from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DistName(SchemaObject):
    config = SchemaField(name='config')
    runtime = SchemaField(name='runtime')

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super(DistName, self).__init__()


class GetAldsResponseV1(SchemaObject):
    product_code = SchemaField(name='productCode')
    serial_number = SchemaField(name='serialNumber')
    software_version = SchemaField(name='softwareVersion')
    hardware_version = SchemaField(name='hardwareVersion')
    vendor_code = SchemaField(name='vendorCode')
    control_protocol = SchemaField(name='controlProtocol')
    aisg_protocol_version = SchemaField(name='aisgProtocolVersion')
    release_id3_gpp = SchemaField(name='releaseId3Gpp')
    availability_status = SchemaField(name='availabilityStatus')
    operational_state = SchemaField(name='operationalState')
    procedural_status = SchemaField(name='proceduralStatus')
    dist_names = SchemaField(name='distNames', klass=DistName, not_null=True)

    def __init__(self, product_code, serial_number, software_version, hardware_version, vendor_code, control_protocol,
                 aisg_protocol_version, release_id3_gpp, availability_status, operational_state, procedural_status,
                 dist_names):
        self.product_code = product_code
        self.serial_number = serial_number
        self.software_version = software_version
        self.hardware_version = hardware_version
        self.vendor_code = vendor_code
        self.control_protocol = control_protocol
        self.aisg_protocol_version = aisg_protocol_version
        self.release_id3_gpp = release_id3_gpp
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.dist_names = dist_names

        super(GetAldsResponseV1, self).__init__()
